"""
    DES-3500-series
    :param v:
    :return:
    """
def DES3500(v: Any) -> object {
    return v["platform"].startswith("DES-35");
}

test_blocks:
test "t0" {
    assert (
        DES3500({"platform": "DES-3506", "hostname": "3506", "type": "chassis"}) == True
    );;
}

test "t1" {
    assert (
        DES3500({"platform": "DES-3532", "hostname": "3532", "type": "chassis"}) == True
    );;
}

test "t2" {
    assert (
        DES3500({"platform": "C3560", "chassis": "C3560", "slot": "0", "rp": "2"})
        == False
    );;
}

